<script setup lang="ts">
import type { ImmediateFeedback } from '../../domain/b2'
defineProps<{ feedback: ImmediateFeedback | null; performanceLevel?: 'Ultra' | 'High' | 'Medium' | 'Performance' }>()
const emit = defineEmits<{ next: []; retry: [] }>()
</script>
<template><section v-if="feedback" class="feedback" :class="{ 'feedback--static': performanceLevel === 'Performance' }" role="status" aria-live="polite"><div class="feedback__mark" aria-hidden="true">{{ feedback.correct === true ? '✓' : feedback.correct === false ? '!' : 'i' }}</div><div><strong>{{ feedback.title }}</strong><p>{{ feedback.message }}</p><small v-if="feedback.errorCategory">规则归因：{{ feedback.errorCategory }}</small></div><button v-if="feedback.nextAction === 'RETRY'" class="feedback__button" type="button" @click="emit('retry')">再练一次</button><button v-else class="feedback__button" type="button" @click="emit('next')">下一题</button></section></template>
<style scoped>.feedback{display:flex;align-items:center;gap:14px;padding:16px;border:1px solid #cfeee3;border-radius:14px;background:#f2fcf8}.feedback:not(.feedback--static){transition:transform 160ms ease}.feedback__mark{display:grid;width:36px;height:36px;flex:0 0 auto;place-items:center;border-radius:12px;color:#246d58;background:#dff5eb;font-weight:900}.feedback strong{display:block}.feedback p{margin:4px 0;color:#666d80;line-height:1.5}.feedback small{color:#666d80}.feedback__button{min-height:40px;margin-left:auto;padding:0 13px;border:1px solid #b7dfd0;border-radius:10px;color:#246d58;background:#fff;font-weight:700}@media(max-width:560px){.feedback{align-items:flex-start;flex-wrap:wrap}.feedback__button{width:100%;margin-left:0}}</style>
